from datetime import date, timedelta
from typing import List

def recur(start: str, rule: str, count: int) -> List[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    result = []

    if parts[0] == "DAILY":
        k = int(parts[1])
        d = start_date
        while len(result) < count:
            if d >= start_date:
                result.append(d.isoformat())
            d += timedelta(days=k)

    elif parts[0] == "WEEKLY":
        k = int(parts[1])
        days = parts[2].split(",")
        weekday_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
        target_weekdays = [weekday_map[d] for d in days]

        # Find Monday of week 0 (week containing start)
        start_weekday = start_date.weekday()
        week0_monday = start_date - timedelta(days=start_weekday)

        week_num = 0
        while len(result) < count:
            if week_num % k == 0:
                for wd in sorted(target_weekdays):
                    d = week0_monday + timedelta(days=week_num * 7 + wd)
                    if d >= start_date:
                        result.append(d.isoformat())
                        if len(result) >= count:
                            break
            week_num += 1

    elif parts[0] == "MONTHLY":
        k = int(parts[1])
        if len(parts) == 3:
            # MONTHLY K D
            d_val = int(parts[2])
            month_num = 0
            while len(result) < count:
                if month_num % k == 0:
                    year = start_date.year + (start_date.month - 1 + month_num) // 12
                    month = (start_date.month - 1 + month_num) % 12 + 1
                    if d_val == -1:
                        # Last day of month
                        if month == 12:
                            next_month = date(year + 1, 1, 1)
                        else:
                            next_month = date(year, month + 1, 1)
                        d = next_month - timedelta(days=1)
                    else:
                        try:
                            d = date(year, month, d_val)
                        except ValueError:
                            d = None
                    if d and d >= start_date:
                        result.append(d.isoformat())
                month_num += 1
        else:
            # MONTHLY K N WD
            n = int(parts[2])
            wd = parts[3]
            weekday_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
            target_weekday = weekday_map[wd]

            month_num = 0
            while len(result) < count:
                if month_num % k == 0:
                    year = start_date.year + (start_date.month - 1 + month_num) // 12
                    month = (start_date.month - 1 + month_num) % 12 + 1
                    first_day = date(year, month, 1)
                    first_wd = first_day.weekday()
                    days_to_first_target = (target_weekday - first_wd) % 7
                    first_target = first_day + timedelta(days=days_to_first_target)

                    if n == -1:
                        # Last occurrence
                        d = first_target + timedelta(days=28)
                        while d.month == month:
                            d += timedelta(days=7)
                        d -= timedelta(days=7)
                    else:
                        d = first_target + timedelta(days=(n - 1) * 7)
                        if d.month != month:
                            d = None

                    if d and d >= start_date:
                        result.append(d.isoformat())
                month_num += 1

    elif parts[0] == "YEARLY":
        k = int(parts[1])
        mm_dd = parts[2]
        mm, dd = map(int, mm_dd.split("-"))

        year_num = 0
        while len(result) < count:
            if year_num % k == 0:
                year = start_date.year + year_num
                try:
                    d = date(year, mm, dd)
                except ValueError:
                    d = None
                if d and d >= start_date:
                    result.append(d.isoformat())
            year_num += 1

    return result
